<?php
/** TEMP PS S1685 ml — DEPLOY naujas mu-plugin petshop-pakartoti.php v1.0.0 + šablonas mu-plugins/ps-sablonai/refill-pakartoti.php; token_get_all, heartbeat, rollback. */
add_action('init', function(){
  if (!isset($_GET['ps_s1685ml'])) return; $o=array('v'=>'S1685 ml'); $f=WPMU_PLUGIN_DIR.'/petshop-pakartoti.php'; $sd=WPMU_PLUGIN_DIR.'/ps-sablonai'; $t=$sd.'/refill-pakartoti.php';
  if(file_exists($f)||class_exists('Petshop_Pakartoti')||file_exists($t)){ $o['STOP']='vardas/klasė/šablonas užimti'; echo json_encode($o); exit; }
  $np=base64_decode(''); $nt=base64_decode(''); if(md5($np)!=='46832bdf34d8fa4b5ea2ecf57fdd28de'||md5($nt)!=='b8363eba07b8e5464177173d4addc85c'){ $o['STOP']='md5 payload'; echo json_encode($o); exit; }
  try { token_get_all($np, TOKEN_PARSE); token_get_all($nt, TOKEN_PARSE); } catch (Throwable $e) { $o['STOP']='ParseError: '.$e->getMessage(); echo json_encode($o); exit; }
  if(!is_dir($sd)) mkdir($sd,0755); file_put_contents($t,$nt); file_put_contents($f,$np); if(function_exists('opcache_invalidate')){ opcache_invalidate($f,true); opcache_invalidate($t,true); } $o['md5']=array(md5_file($f),md5_file($t));
  $hb=wp_remote_get(home_url('/'),array('timeout'=>20,'sslverify'=>false)); $code=is_wp_error($hb)?0:wp_remote_retrieve_response_code($hb); $o['heartbeat']=$code; if($code>=500||$code===0){ unlink($f); unlink($t); $o['ROLLBACK']='ištrinta'; }
  header('Content-Type: application/json; charset=utf-8'); echo json_encode($o,JSON_UNESCAPED_UNICODE); exit;
});
